def countTriplets(arr: list[int], target: int) -> int:
    arr.sort()
    count = 0
    n = len(arr)
    for i in range(n - 2):
        l, r = i + 1, n - 1
        while l < r:
            if arr[i] + arr[l] + arr[r] < target:
                count += (r - l)
                l += 1
            else:
                r -= 1
    return count

