function findUnsortedSubarray(nums) {
    const n = nums.length;
    let maxVal = -Infinity, minVal = Infinity, l = -1, r = -1;
    for (let i = 0; i < n; i++) {
        maxVal = Math.max(maxVal, nums[i]);
        if (nums[i] < maxVal) r = i;
    }
    for (let i = n - 1; i >= 0; i--) {
        minVal = Math.min(minVal, nums[i]);
        if (nums[i] > minVal) l = i;
    }
    return r !== -1 ? r - l + 1 : 0;
}

