def minEatingSpeed(piles: list[int], h: int) -> int:
    import math
    l, r = 1, max(piles)
    ans = r
    while l <= r:
        k = (l + r) // 2
        hours = sum(math.ceil(p / k) for p in piles)
        if hours <= h:
            ans = k
            r = k - 1
        else:
            l = k + 1
    return ans

