def generateParenthesis(n: int) -> list[str]:
    res = []
    def backtrack(open_c, close_c, path):
        if len(path) == 2 * n:
            res.append(''.join(path))
            return
        if open_c < n:
            path.append('(')
            backtrack(open_c + 1, close_c, path)
            path.pop()
        if close_c < open_c:
            path.append(')')
            backtrack(open_c, close_c + 1, path)
            path.pop()
    backtrack(0, 0, [])
    return res

